<?php

namespace App\Libraries;

/**
 * Sixth batch (200 entries): the InterLink Upload Form "Generate Report" button, 1-click sending with the
 * "NEXUS-L InterLink Sender" extension, file-generation requests (report PDFs, Access PDFs, exports), data lookups,
 * DTR material and bonding troubleshooting, standards and PASS / TOLERABLE / FAIL ratings, Inbox, Designer and Help.
 * Rating thresholds are never hardcoded here: the numbers live in the standards table (tbl_dtr_standards), which is
 * imported from the QC Lab Access databases. Loaded by `php spark brain:seed`.
 */
class BrainSeed6
{
    /** Titles of built-in answers made wrong by Generate Report and the 1-click sender (it now attaches the PDF). */
    public const RETIRE = ['Can NEXUS-L attach the PDF to InterLink?'];

    /** @return list<array<string,mixed>> */
    public static function all(): array
    {
        $o = static fn (string $label, string $url, bool $admin = false): array => ['type' => 'open', 'label' => $label, 'url' => $url] + ($admin ? ['role' => 'admin'] : []);
        $k = static fn (string $title, string $keywords, string $body, array $steps = [], array $extra = []): array => array_merge(['title' => $title, 'keywords' => $keywords, 'body' => $body, 'steps' => $steps], $extra);
        $dtr  = ['page_match' => 'dtr'];
        $il   = ['page_match' => 'interlink'];
        $adm  = ['role_min' => 'admin'];
        $pdf  = ['page_match' => 'dtr', 'diagnose' => 'pdf_engine'];
        $goIl = ['actions' => [$o('Open InterLink Sync', 'interlink')]];
        $goTr = ['actions' => [$o('Open Lab Tracker', 'dtr?tab=tracker')]];
        $goMt = ['actions' => [$o('Open Material Tests', 'dtr?tab=material')]];
        $goBd = ['actions' => [$o('Open Shoe Bonding', 'dtr?tab=bonding')]];
        $goCa = ['actions' => [$o('Open Calculators & Standards', 'dtr?tab=calculators')]];

        return [
            // =========================================================== Upload Form: Generate Report (25)
            $k('What does the Generate Report button on the Upload Form do?', 'generate report button, generate report upload form, what is generate report, green generate report, generate report beside browse, report attachment generate', 'On the InterLink Upload Form, tab 2 (Upload Result), the Report Attachment (PDF) row has a green "Generate Report" button beside Browse. It finds the Lab Reference linked to the application, opens its Digital Test Report record in the background, renders the official VF print sheet to PDF and attaches it as <LabRef>_TestReport.pdf. You can then press View or Download to check it.', ['Open the application on the Upload Form.', 'Go to tab 2 (Upload Result).', 'Press Generate Report beside Browse.', 'Wait for "Report PDF ready", then press View to check it.'], $il + $goIl),
            $k('How do I generate the test report PDF for InterLink?', 'generate test report pdf, make report pdf for interlink, create pdf for interlink, build the report pdf, interlink report pdf, testreport pdf', 'Open the application on the InterLink Upload Form, go to tab 2 (Upload Result) and press "Generate Report" in the Report Attachment (PDF) row. NEXUS-L builds <LabRef>_TestReport.pdf from the Lab Reference and attaches it. The 1-Click Send uses this same PDF.', ['Open the application on the Upload Form.', 'Tab 2 > Report Attachment (PDF) > Generate Report.', 'Press View to check the PDF.', 'Send it with 1-Click Send or attach it in InterLink yourself.'], $il + $goIl),
            $k('Generate Report asks me to enter a Lab Ref No.', 'generate report asks lab ref, generate report asking for lab ref number, asking me for a lab ref, enter the lab ref no to build, no lab reference is linked, prompt lab ref generate, generate asks for lab reference', 'No Lab Reference is linked to this application yet, so NEXUS-L asks which one to build the report from. Type the Lab Ref No. (for example DTP20260929VH-12) and press OK. To avoid the question, pick the Lab Reference in the Pre-Sync dialog first or save the report with its Lab Ref.', [], $il),
            $k('Which Lab Reference does Generate Report use?', 'which lab reference generate report, generate report which lab ref, how lab ref chosen generate, lab ref used for pdf, linked lab reference', 'It uses, in this order: the Lab Reference picked in the Pre-Sync dialog, the Lab Ref saved on the InterLink report, the Lab Reference whose TR No. equals the Application No., or the name of an attached <LabRef>_TestReport.pdf. If none is found it asks you.', [], $il),
            $k('"has no Digital Test Report form to print"', 'has no digital test report form to print, no dtr form to print, generate report no form, cannot generate report form, no form slug', 'The Lab Reference exists in the list but has no saved Digital Test Report record to print. Open QC Lab Reports, create or save the report for that Lab Ref No. (Material Tests or Shoe Bonding), then press Generate Report again.', [], $il + $goTr),
            $k('"Could not generate the report"', 'could not generate the report, generate report failed, generate report error, generating stuck, report pdf generation failed', 'The report sheet or the PDF engine failed. Check that the Lab Ref No. opens and previews in QC Lab Reports (Print / Preview). If the preview works but the PDF still fails, the server PDF engine (Chrome / Edge) may be down: tell an administrator, and use Browse to attach a PDF you saved from the preview meanwhile.', [], $il + ['diagnose' => 'pdf_engine']),
            $k('Generate Report keeps saying Generating...', 'generating forever, generate report slow, generating takes long, generate report hangs, generate report spinning', 'Building the PDF opens the report in a hidden frame and renders it on the server, which normally takes a few seconds (bonding reports a little longer, because the Access result page is added). If it takes over a minute, refresh the page (Ctrl + F5) and try again; if it repeats, tell an administrator.', [], $il),
            $k('How do I check the generated report PDF before sending?', 'check generated pdf, view generated report, view button attachment, preview attached pdf, open attached pdf', 'After Generate Report (or Browse), the attachment line shows the file name and size with View and Download. View opens the PDF in a new tab; Download saves <LabRef>_TestReport.pdf to your computer.', [], $il),
            $k('What is the name of the generated report file?', 'generated file name, testreport pdf name, labref testreport, attachment name format, pdf named', 'The file is named <LabRef>_TestReport.pdf, for example DTP20260929VH-12_TestReport.pdf. The same name is put in the Report Attachment box of the Upload Form.', [], $il),
            $k('Can I attach my own PDF instead of generating one?', 'attach my own pdf, browse pdf, choose pdf file, use my own report file, browse button pdf, select pdf upload form', 'Yes. Press Browse... in the Report Attachment (PDF) row and choose the PDF file. Only PDF files are accepted. The chosen file replaces any generated one and is the one 1-Click Send attaches.', [], $il),
            $k('"Please choose a PDF file"', 'please choose a pdf file, browse wrong file, not a pdf, browse rejects file, only pdf allowed', 'The Report Attachment only takes PDF files. Choose a .pdf file, or press Generate Report to build the PDF from the Lab Reference.', [], $il),
            $k('Does Generate Report send anything to InterLink?', 'generate report send interlink, does generate submit, generate uploads to interlink, generate report submitted', 'No. Generate Report only builds and attaches the PDF inside NEXUS-L. The report reaches InterLink when you send it with 1-Click Send (the NEXUS-L InterLink Sender) or attach it and press Submit in InterLink yourself.', [], $il),
            $k('Is the generated PDF the same as Download PDF in the report preview?', 'generated pdf same as preview, same as download pdf, generate vs download pdf, identical pdf, sheet pdf same', 'Yes. Both use the same VF print sheet and the same server renderer (dtr/sheet-pdf), fitted to one A4 page. For bonding reports the official Access machine-result page is added as page 2 when it is available.', [], $il),
            $k('The generated PDF shows the wrong report', 'generated pdf wrong report, wrong record in pdf, generate wrong lab ref, pdf other sample, generated wrong data', 'Check the Lab Reference shown in the toast and attachment line. If it is not the right one, pick the right Lab Reference in the Pre-Sync dialog (or type it when asked) and press Generate Report again. If the right Lab Ref still prints another record, tell an administrator with both Lab Ref numbers.', [], $il),
            $k('The generated PDF has old values', 'generated pdf old values, pdf not updated, generate shows old data, pdf before my changes, stale pdf', 'The PDF is built from the saved report. Save the report in QC Lab Reports first (Save Report), then press Generate Report again so the new values are used.', [], $il),
            $k('Can I generate a bonding report PDF for InterLink?', 'generate bonding pdf interlink, whole shoe bonding pdf upload, bonding report attachment, shb pdf interlink, u60 pdf interlink', 'Yes. For a Whole Shoe Bonding Lab Ref (for example ...SHB14-L) Generate Report builds the bonding sheet with the shoe diagram, and adds the official Access machine-result page as page 2 when it exists.', [], $il),
            $k('Where do I find the Report Attachment row?', 'where report attachment, find attachment row, job_dummy_004, attachment field upload form, report attachment pdf where', 'Open the application on the InterLink Upload Form and switch to tab 2 (Upload Result). The first row, "Report Attachment (PDF)" (JOB_DUMMY_004), has Generate Report, Browse... and the View / Download links.', [], $il + $goIl),
            $k('The attachment is gone after I reloaded the page', 'attachment gone after reload, pdf lost refresh, generated pdf disappeared, attachment cleared, lost attached pdf', 'The generated or browsed PDF is kept only in the open page until it is sent. After a reload press Generate Report (or Browse) again; it takes a few seconds.', [], $il),
            $k('Can I generate the report for another application?', 'generate for another application, switch application pdf, other application attachment, attachment belongs to application', 'Yes, open that application first. The attached PDF belongs to the application that was open when it was made; 1-Click Send only reuses it for the same Application No. and builds a new one for any other.', [], $il),
            $k('Generate Report button is greyed out', 'generate report disabled, generate button grey, cannot press generate, generate report not clickable', 'The button is disabled while a PDF is being built. Wait until it shows "Generate Report" again. If it stays grey, refresh the page with Ctrl + F5.', [], $il),
            $k('How do I save the generated report to my computer?', 'save generated report, download generated pdf, keep a copy pdf, save testreport pdf, download attachment', 'Press Download on the attachment line under Report Attachment (PDF). The file is saved as <LabRef>_TestReport.pdf in your Downloads folder.', [], $il),
            $k('Can I generate the PDF when the report status is not Complete?', 'generate incomplete report, draft report pdf, status not complete pdf, pending report generate', 'The PDF prints what is saved, so an incomplete report produces an incomplete sheet and may have no overall stamp. Finish the readings, set the Status and save before generating the PDF that goes to InterLink.', [], $il),
            $k('Generate Report says the Lab Ref is not found', 'generate lab ref not found, labref detail not found, lab reference not found interlink, generate unknown lab ref', 'The Lab Ref No. is not in the NEXUS-L list. Check the number (date part, letters and the -L / -R ending). If the report was never saved, create and save it in QC Lab Reports first.', [], $il + $goTr),
            $k('Why does Generate Report open nothing on screen?', 'generate opens nothing, hidden frame, no window generate, where does generate open, invisible report', 'It works in a hidden frame on purpose: the report opens, the sheet is rendered to PDF and the frame closes. You only see the toast and the attachment line. Press View to see the PDF.', [], $il),
            $k('Do I need the extension to use Generate Report?', 'extension needed for generate, sender needed generate report, generate without extension, generate needs chrome extension', 'No. Generate Report, Browse, View and Download work without any extension. The NEXUS-L InterLink Sender is only needed for 1-Click Send.', [], $il),

            // =========================================================== 1-click send and the extension (25)
            $k('What is the NEXUS-L InterLink Sender?', 'nexus-l interlink sender, what is the sender, can nexus-l attach the pdf to interlink, attach pdf to interlink automatically, upload pdf to interlink, interlink sender extension, chrome extension interlink, sender extension', 'A small Chrome extension for 1-Click Send. In your own browser, with your own InterLink sign-in, it opens the InterLink Upload Form, switches it to Edit when needed, fills the boxes, attaches the report PDF and presses Submit, then tells NEXUS-L the result. It stores nothing after the job.', [], $il + $goIl),
            $k('How do I install the NEXUS-L InterLink Sender?', 'install sender, install extension, load unpacked, download the sender, sender zip, add extension chrome, install interlink sender', 'Press Send once: if the sender is missing, NEXUS-L shows the install steps and a "Download the sender" button.', ['Download the sender zip and unzip it to a folder you keep (for example Documents).', 'Open chrome://extensions and turn on Developer mode (top right).', 'Press Load unpacked and choose the unzipped folder.', 'Reload the NEXUS-L page and press Send again.'], $il + $goIl),
            $k('The install the sender window keeps appearing', 'install window keeps appearing, sender not detected, extension installed but asks again, install the nexus-l interlink sender again', 'NEXUS-L does not see the extension on this page. Check chrome://extensions: the NEXUS-L InterLink Sender must be switched on. Then reload the NEXUS-L page (Ctrl + F5). Open NEXUS-L at http://192.168.32.43/NEXUS-L/; the sender only works on that address.', [], $il),
            $k('How do I send a report to InterLink with 1 click?', 'send with 1 click, one click send, 1-click send report, send to interlink one click, send report button', 'Pick the Application No. and the Lab Reference, then press "2. Send to InterLink (1 click)" (or Submit & Send Report to InterLink on the Upload Form). Sign in to InterLink in your own Chrome first. The sender opens InterLink in a new tab, fills it, attaches <LabRef>_TestReport.pdf and submits, and a message tells you the result.', ['Sign in to InterLink in your Chrome with your own account.', 'In NEXUS-L pick the Application No. and the Lab Reference.', 'Optional: Generate Report and View to check the PDF.', 'Press Send to InterLink (1 click) and watch the messages.'], $il + $goIl),
            $k('Does 1-Click Send use the PDF I generated?', '1-click send which pdf, sender uses generated pdf, send attached pdf, browsed pdf sent, same pdf sent', 'Yes. If you generated or browsed a PDF on the Upload Form for the same application, it is sent as it is. Only when nothing is attached does the sender build the report PDF from the Lab Reference.', [], $il),
            $k('"No Lab Reference is linked to ... so there is no report to attach"', 'no lab reference is linked, no report to attach, send no lab ref, 1 click no lab reference', 'The application has no Lab Reference and no attached PDF. Pick the Lab Reference in the list (or in the Pre-Sync dialog), or attach a PDF with Generate Report / Browse, then send again.', [], $il),
            $k('"The InterLink tab ... was closed before it was sent"', 'tab was closed before it was sent, closed interlink tab, send cancelled tab closed, interlink tab closed', 'The sender works in the InterLink tab it opened; closing that tab stops the job. Press Send again and leave the new tab open until NEXUS-L says it was submitted.', [], $il),
            $k('"InterLink did not reach the Submit step"', 'did not reach the submit step, sender stopped before submit, finish it in the interlink tab, sender gave up', 'The InterLink form did not respond as expected (slow page, a question box, or signed out). Finish the form in the InterLink tab yourself: check the filled boxes and the attachment, then press Submit.', [], $il),
            $k('"InterLink did not accept" the report', 'interlink did not accept, rejected by interlink, submit refused, interlink validation error, did not accept application', 'InterLink refused the submission, usually for a missing required box or a wrong value. Look at the InterLink tab for the red message, correct it there and press Submit, or fix the report in NEXUS-L and send again.', [], $il),
            $k('How do I know the report was submitted?', 'was submitted to interlink, submitted message, send success message, how know sent, confirmation sender', 'When the sender finishes, NEXUS-L shows a green message "<Application No.> was submitted to InterLink with <file>.pdf". You can also open the application in InterLink and check its status and attachment.', [], $il),
            $k('Does the sender need my InterLink password?', 'sender password, extension stores password, sender login, extension credentials, sender sees my password', 'No. The sender uses the InterLink sign-in that is already open in your Chrome. It never asks for, sees or stores your password, and it keeps nothing after the job.', [], $il),
            $k('Can I use 1-Click Send in Edge or Firefox?', 'sender edge, sender firefox, extension other browser, 1-click send edge, which browser sender', 'The sender is a Chrome extension. Use Google Chrome for 1-Click Send. In other browsers use Generate Report > Download and attach the PDF in InterLink yourself.', [], $il),
            $k('Can I send several applications at once?', 'send many applications, batch send interlink, send multiple at once, bulk send, several sends', 'Send them one by one: each Send opens its own InterLink tab. Wait for the result message of one before starting the next so you can check each submission.', [], $il),
            $k('The sender filled the form but did not attach the PDF', 'sender no attachment, pdf not attached interlink, attachment missing after send, sender attach failed', 'Check the message in NEXUS-L. If the attachment is missing on the InterLink form, attach the PDF there yourself: press Download on the NEXUS-L attachment line and choose that file in InterLink, then Submit.', [], $il),
            $k('How do I update the NEXUS-L InterLink Sender?', 'update sender, new sender version, reload extension, sender update, extension update', 'Download the new sender zip, unzip it over the old folder, then open chrome://extensions and press the reload arrow on NEXUS-L InterLink Sender. Reload the NEXUS-L page afterwards.', [], $il),
            $k('How do I remove the sender extension?', 'remove sender, uninstall extension, delete sender extension, turn off sender', 'Open chrome://extensions and press Remove on NEXUS-L InterLink Sender (or switch it off). 1-Click Send then shows the install steps again; Generate Report still works.', [], $il),
            $k('Chrome warns about developer mode extensions', 'developer mode warning, disable developer mode extensions, chrome warning extension, unpacked extension warning', 'Chrome shows this for every extension loaded with Load unpacked. It is expected for the NEXUS-L InterLink Sender; close the warning (do not disable the extension).', [], $il),
            $k('Why does 1-Click Send open a new InterLink tab?', 'why new tab send, sender opens tab, interlink new tab, send opens window', 'The report must be submitted from your own browser with your own InterLink sign-in, so the sender works in a normal InterLink tab. Leave it open until NEXUS-L reports the result; you can then close it.', [], $il),
            $k('1-Click Send says Preparing but nothing else happens', 'preparing nothing happens, send stuck preparing, sender no tab opened, send does nothing', 'Check that the NEXUS-L InterLink Sender is switched on and that Chrome allows NEXUS-L to open tabs. Reload NEXUS-L (Ctrl + F5) and send again. If the message "Could not prepare the values" appears, tell an administrator.', [], $il),
            $k('"Could not prepare the values"', 'could not prepare the values, prepare failed, center fill error, prepare values error', 'NEXUS-L could not read the Lab Reference or application on the server. Check the Application No. and the Lab Reference, refresh the page and try again. If it repeats, tell an administrator with the time and the Application No.', [], $il),
            $k('"Could not create the report PDF"', 'could not create the report pdf, sender pdf failed, report pdf creation error send', 'The sender could not build the report PDF. Open the Lab Ref in QC Lab Reports and check Print / Preview works. As a workaround, Download PDF from the preview and attach it with Browse, then send again.', [], $il + ['diagnose' => 'pdf_engine']),
            $k('Does the sender switch InterLink to Edit mode?', 'sender edit mode, interlink edit button, form read only interlink, switch to edit', 'Yes. If the InterLink Upload Form opens read-only, the sender presses Edit first, then fills the boxes, attaches the PDF and submits.', [], $il),
            $k('Who is recorded as the sender in InterLink?', 'recorded as sender, who submitted interlink, submitter name, whose name interlink', 'The person signed in to InterLink in that Chrome. That is why each PIC sends with their own InterLink account.', [], $il),
            $k('Can I check the filled InterLink form before it is submitted?', 'check before submit, review before sending, stop before submit, manual submit option', '1-Click Send submits for you. If you want to review first, use the fill bookmark path instead (Copy fill data, open the form, click the NEXUS-L fill bookmark, review and press Submit yourself), or attach the generated PDF manually.', [], $il),
            $k('My InterLink sign-in expired during 1-Click Send', 'signed out during send, interlink login page during send, session expired sender, sender sign in page', 'The InterLink tab shows the sign-in page, so the sender stops. Sign in again in that tab with your own account, then press Send again in NEXUS-L.', [], $il),

            // =========================================================== Upload Form, search grid and Sync Center (15)
            $k('What are the two tabs of the InterLink Upload Form?', 'upload form tabs, tab 1 tab 2 upload form, upload result tab, vf corporation report online upload form, upload form layout', 'Tab 1 is the VF Corporation Report Online Upload Form (header and specifications). Tab 2 is Upload Result: Report Attachment (PDF), Sample Information, Test Item Result and Test Item Result For Reading.', [], $il),
            $k('How do I open an application on the Upload Form?', 'open application upload form, open uploadform, open u form, go to upload form, open application no', 'In InterLink Sync, find the application in the search grid and open it with U (Upload Form). Use "Back to Search Grid" to return to the list.', [], $il + $goIl),
            $k('How do I fill the Upload Form from a Lab Reference?', 'fill upload form from lab reference, pre-sync fill tabs, populate upload form, labref fills fields, load lab ref into form', 'Open the Pre-Sync dialog, pick the Lab Reference in the list (filter by category if needed) and confirm. The matching boxes on tab 1 and the sub-grids on tab 2 are filled and marked "Synced".', [], $il),
            $k('What does the Synced tag on a field mean?', 'synced tag, check synced field, synced label upload form, field marked synced', '"Synced" marks a box that was filled from the Lab Reference (or the attachment that was generated). Boxes without the tag were not changed by NEXUS-L.', [], $il),
            $k('What is Save Company Report Data?', 'save company report data, company report save, save interlink report data, save upload form', 'It saves the values of the Upload Form in NEXUS-L (Company Reports) so you can come back to them. It does not submit anything to InterLink.', [], $il),
            $k('How do I export the InterLink search grid to Excel?', 'export interlink grid, export to excel interlink, export test item, export reading, interlink excel export', 'Above the InterLink search grid use Export to Excel (the list), Export to Excel Test Item (test items) or Export to Excel Reading (specimen readings).', [], $il + $goIl),
            $k('What are Sample Information, Test Item Result and Reading grids?', 'sample information grid, test item result grid, reading grid, job_dummy_007, job_dummy_008, job_dummy_013, sub grids', 'They are the three sub-grids of tab 2: Sample Information (the samples), Test Item Result (one row per test with its result) and Test Item Result For Reading (the specimen readings). The Pre-Sync dialog fills them from the Lab Reference.', [], $il),
            $k('How do I filter the Lab References in the Pre-Sync dialog by type?', 'filter pre-sync category, labref combo category, filter fabric leather bonding sync, category filter dialog', 'Use the category filter above the Lab Reference list (Fabric, Leather, WST, FTHL, Hardware, Label, SKLFM, Rubber, Box, Insole, Whole Shoe Bonding) and type part of the Lab Ref, material or style to narrow it.', [], $il),
            $k('Which Application No. should I type in Send a report to InterLink?', 'which application no type, application no format, a00 application number, application number example', 'Type the InterLink Application No. of the request, for example A005953693; the list suggests the ones already stored in NEXUS-L. Then pick the Lab Reference that belongs to it.', [], $il),
            $k('How do I search for a Lab Reference in the Send panel?', 'search lab reference send panel, sc search, search lab ref tr material style, find labref send', 'Type part of the Lab Ref, TR No., material or style in the search box of "Send a report to InterLink" and choose a type in the drop-down. Click a row to select it.', [], $il),
            $k('The Send to InterLink (1 click) button is disabled', 'send button disabled, 1 click button grey, cannot press send, send to interlink disabled', 'Choose both an Application No. and a Lab Reference (click a row in the list). The button is enabled once both are set.', [], $il),
            $k('Can I send a report that is still TOLERABLE or FAIL?', 'send tolerable report, send fail report interlink, failed report submit, send not pass', 'NEXUS-L does not block it; the report shows the real result. Follow your lab procedure: failed or tolerable results usually need the supervisor\'s approval before the PIC sends them.', [], $il),
            $k('Where is the history of what I sent?', 'history what i sent, sent history, sync history sent, list of sent reports, my sent reports', 'Sync History in InterLink Sync lists what was prepared in NEXUS-L. The final proof is the application in InterLink itself (status and attachment).', [], $il + $goIl),
            $k('The Upload Form fields are in the wrong place compared with InterLink', 'upload form different interlink, fields wrong place, interlink form changed, layout differs interlink', 'InterLink may have changed its form. Tell an administrator which box moved; the fill and the sender match boxes by their InterLink names, so a renamed box must be updated in NEXUS-L.', [], $il),
            $k('Can I edit the values after they are filled from the Lab Reference?', 'edit filled values, change synced value, overwrite filled box, correct filled field', 'Yes, type over any box on the Upload Form before sending. Remember that the PDF shows the saved report, so fix real result errors in the report itself and generate the PDF again.', [], $il),

            // =========================================================== generate a file / exports (25)
            $k('Make a PDF of a lab report', 'make a pdf, create pdf of report, give me the pdf, pdf of lab ref, generate pdf report, produce pdf', 'Ask me "pdf DTP20261012FAA8-L" (your Lab Ref No.): I find the report and give you a button that opens it with the print preview, where Download PDF saves it. Or open the report in QC Lab Reports and press Print / Preview > Download PDF.', ['Open the report (Lab Tracker > Open Form).', 'Press Print / Preview.', 'Press Download PDF (or Print Report / Save as PDF).'], $dtr + $goTr),
            $k('Open the print preview of a report directly', 'open print preview directly, preview link, open preview lab ref, deep link preview, preview=1', 'Ask me "preview <Lab Ref No.>" and press "Open the print / PDF preview". The link opens dtr?open=<form>:<id>&preview=1, which loads the record and opens its preview with Download PDF and Print.', [], $dtr),
            $k('Download the official Access PDF of a bonding report', 'download access pdf bonding, official access pdf, bonding access pdf, accdb pdf bonding, access report pdf download', 'Open the bonding report, press Print / Preview and use "Download Official Access PDF". It calls dtr/bonding-access-pdf with the BondingTestID and the side (Left / Right) and returns the report made from the original Access layout.', [], $pdf + $goBd),
            $k('Generate the left and right bonding PDFs', 'left and right pdf, both sides pdf, l and r bonding pdf, generate left right report, pdf for each shoe', 'Each side is its own Lab Ref (ending -L and -R). Open the -L record, preview and download its PDF, then do the same for the -R record. The official Access PDF also takes the side.', [], $dtr + $goBd),
            $k('Export a report to Excel', 'export report to excel, excel of a report, report as excel, xlsx of lab report, report spreadsheet', 'A single report has no Excel export; use Download PDF from the preview. For lists, InterLink Sync has Export to Excel, Export to Excel Test Item and Export to Excel Reading above its search grid.', [], $dtr),
            $k('Export the machine readings', 'export machine readings, get readings file, copy machine file, readings export, raw readings', 'The readings come from the machine file on the machine PC / share. Ask an administrator for a copy of the file, or ask me "check machine file for <Lab Ref No.>" to see whether it is found and how many readings it has.', [], $dtr),
            $k('Generate a report PDF for a Lab Ref I do not have open', 'pdf for lab ref not open, generate pdf by lab ref, pdf without opening, pdf from number', 'Type in the assistant "pdf <Lab Ref No.>" (for example "pdf DTP20261012FAA8-L"). I give buttons to open the record and its print preview; press Download PDF there.', [], $dtr),
            $k('How do I save a report as PDF with the browser?', 'save as pdf browser, print to pdf, microsoft print to pdf, browser pdf, ctrl p pdf', 'In the preview press Print Report / Save as PDF, choose "Save as PDF" as the printer, A4, margins Default, then Save. Use this when Download PDF is not available.', [], $dtr),
            $k('Where does dtr/sheet-pdf come from?', 'dtr sheet-pdf, sheet pdf route, server pdf renderer, pdf engine route, headless chrome pdf', 'dtr/sheet-pdf is the NEXUS-L server route that turns the report sheet shown in the preview into an A4 PDF with headless Chrome / Edge. Download PDF, Generate Report and 1-Click Send all use it.', [], $pdf + $adm),
            $k('Make a PDF of the bonding shoe diagram', 'pdf of shoe diagram, diagram pdf, bonding diagram pdf, shoe sketch pdf', 'The shoe diagram is part of the bonding report sheet. Open the bonding report, press Print / Preview and Download PDF: the PDF includes the diagram with every spot value.', [], $dtr + $goBd),
            $k('Can the assistant send me the PDF file?', 'assistant send pdf, bot make file, assistant attach pdf, bot download file, assistant generate file', 'I do not create or send files myself. I find the report and give you buttons that open it or its print preview; you press Download PDF there. On the InterLink Upload Form, Generate Report builds the PDF for the attachment.', [], []),
            $k('Download the PDF of a Fabric report', 'fabric report pdf, fbu pdf, fbl pdf, fabric pdf download, canvas report pdf', 'Open the Fabric Test Report (FBU / FBL) for the Lab Ref, press Print / Preview and Download PDF. Or ask me "pdf <Lab Ref No.>".', [], $dtr + $goMt),
            $k('Download the PDF of a Leather report', 'leather report pdf, leu pdf, lel pdf, suede report pdf, leather pdf download', 'Open the Leather Test Report (LEU / LEL) for the Lab Ref, press Print / Preview and Download PDF. Or ask me "pdf <Lab Ref No.>".', [], $dtr + $goMt),
            $k('Download the PDF of a Rubber outsole report', 'rubber report pdf, rb pdf, outsole pdf, rubber outsole pdf download', 'Open the Rubber Outsole Test Report (RB) for the Lab Ref, press Print / Preview and Download PDF.', [], $dtr + $goMt),
            $k('Download the PDF of a Hardware or Label report', 'hardware report pdf, label report pdf, eyelet pdf, zipper pdf, woven label pdf, size label pdf', 'Open the Hardware (EY / GR / ZP) or Label (WL / SL / TL) form for the Lab Ref, press Print / Preview and Download PDF.', [], $dtr + $goMt),
