            $k('The downloaded PDF has two pages', 'pdf two pages, second page pdf, extra page pdf, pdf page 2', 'For bonding reports page 2 is the official Access machine-result page, added on purpose. For material reports the sheet is scaled to one A4 page; if it still breaks, refresh (Ctrl + F5) and download again, and tell an administrator if it repeats.', [], $dtr),
            $k('Can I email the PDF from NEXUS-L?', 'email pdf from nexus-l, send pdf email, mail report, email report directly', 'NEXUS-L does not send email. Download the PDF and attach it in your email, or send it to a colleague through the Inbox (it accepts files).', [], $dtr + ['actions' => [$o('Open Inbox', 'inbox')]]),
            $k('Send the report PDF to a colleague in the Inbox', 'send pdf to colleague, share pdf inbox, attach pdf chat, send report file inbox', 'Download the PDF from the preview, open the Inbox, choose the colleague and attach the file with the paper-clip button.', [], ['actions' => [$o('Open Inbox', 'inbox')]]),
            $k('Get the PDF that was submitted to InterLink', 'pdf submitted interlink, copy of sent pdf, which pdf was sent, retrieve sent pdf', 'NEXUS-L keeps no copy of the sent file. Open the application in InterLink to download its attachment, or generate it again from the Lab Reference (it is the same report if nothing changed).', [], $il),
            $k('Export the standards list', 'export standards, standards excel, list of standards download, print standards', 'There is no standards export button. The Live Master Lookup Explorer in Calculators & Standards shows them on screen; ask an administrator for a full export from the standards table.', [], $dtr + $goCa),

