            $k('Find a report by TR No.', 'find by tr no, search tr number, tr no lookup, test report number search', 'Type the TR No. (for example TR20261009001) in the Lab Tracker search box. You can also ask me "open <Lab Ref No.>" if you know the Lab Ref.', [], $dtr + $goTr),
