            $k('List the bonding reports of a style', 'bonding reports of style, shb by style, bonding list style, whole shoe bonding style search', 'Open Shoe Bonding and search the bonding list by style, or type the style in the Lab Tracker and filter to Whole Shoe Bonding.', [], $dtr + $goBd),
