            $k('Which reports are still pending?', 'reports pending, incomplete reports, status pending, not complete reports, open reports', 'In the Lab Tracker look at the Status and Result columns: reports without a final result are not complete yet. Open each one to finish it.', [], $dtr + $goTr),
            $k('How many reports are in NEXUS-L?', 'how many reports total, total reports, report count, number of lab reports', 'The number next to Lab Tracker in the QC Lab Reports tabs is the total number of reports in NEXUS-L. The Dashboard cards show more counts.', [], $dtr + $goTr),
            $k('Show me the DSR data of an MTL', 'dsr data of mtl, dsr lookup, show dsr, dsr record', 'Use the Live Master Lookup Explorer in Calculators & Standards and search the MTL, or type the MTL on the material form and press Auto-Lookup Material / PO / DSR.', [], $dtr + $goCa),
            $k('What material type is this Material Code?', 'material type of code, material master type, what type material code, material description lookup', 'Search the code in the Live Master Lookup Explorer (Calculators & Standards), or type it on the form and press Tab: the description and material type come from the material master.', [], $dtr + $goCa),
            $k('Show the shoe record of a production code', 'shoe record production code, po lot shoe record, prodcode lookup, shoe master lookup', 'Search the production code in the Live Master Lookup Explorer, or type it in the PO / Lot box on the form and press Tab to fill style, colour and PO.', [], $dtr + $goCa),
            $k('Find the reports from a date range', 'date range reports, reports between dates, from to date, reports this week', 'Lab Ref Nos. start with DTP and the date, so type for example DTP202610 in the Lab Tracker search to see October 2026, or DTP20261012 for one day.', [], $dtr + $goTr),
            $k('Which application is this Lab Ref linked to?', 'application of lab ref, linked application, lab ref application no, tr no application', 'In the Upload Form the Lab Reference whose TR No. equals the Application No. is linked automatically. Otherwise check the Company Reports / Sync History in InterLink Sync for the Lab Ref.', [], $il),
            $k('Is there a report for this Lab Ref?', 'is there a report, does lab ref exist, report exists, check lab ref exists', 'Ask me "find <Lab Ref No.>". If it exists I show its type and result; if not, I tell you and offer the Lab Tracker so you can create it.', [], $dtr),
            $k('Show the readings of a report', 'show readings, see specimen values, readings of report, view readings', 'Open the report from the Lab Tracker; the readings are in the test sections of the form, and the print preview shows them on the sheet.', [], $dtr + $goTr),
            $k('Compare two reports', 'compare two reports, compare lab refs, side by side reports, difference between reports', 'Open NEXUS-L in a second browser tab and open the other report there, or download both PDFs and compare them. Left and right bonding reports are compared on their own sheets.', [], $dtr),
            $k('How many spots does this bonding report have?', 'how many spots report, spot count bonding report, number of points this shoe, spots of style', 'Open the bonding report; Max Points shows the number of spots used for that shoe and the diagram shows them all. The spot rules come from the style and size.', [], $dtr + $goBd),

            // =========================================================== DTR material forms troubleshooting (20)
            $k('+ New Record does nothing', 'new record does nothing, new record button not working, cannot create record, new record no form', 'Choose the material form first (Material Tests > form selector), then press + New Record. If nothing happens, refresh the page (Ctrl + F5).', [], $dtr + $goMt),
            $k('Save Report says the Lab Ref is required', 'save lab ref required, save needs lab ref, cannot save without lab ref, labref required', 'Every report needs its Lab Ref No. Type it in the Lab Ref No. box (for example DTP20261009FBU-1) and save again.', [], $dtr),
            $k('The Material Type list is empty', 'material type list empty, no material type options, material type dropdown blank, mat type empty', 'Each form has its own Material Types (for example Canvas, Suede, Rubber). Check you opened the right form; if the list stays empty refresh the page, then tell an administrator.', [], $dtr),
            $k('I chose the wrong Material Type', 'wrong material type, changed material type, material type mistake, fix material type', 'Choose the right Material Type and press Run Smart Standards & Lookup (Refresh & Apply Smart Standards). The standards and ratings are recalculated for the new type. Save again.', [], $dtr),
            $k('Run Smart Standards & Lookup does nothing', 'smart standards nothing, run smart standards not working, standards not applied, lookup button nothing', 'It needs the Material Type (and, where it applies, the thickness). Fill them and press it again. If no standard exists for that type, the standard boxes stay empty: tell an administrator.', [], $dtr),
            $k('What does Show / Hide All Fields do?', 'show hide all fields, hidden fields material form, show all fields, toggle fields', 'It shows every box of the form, including the ones hidden for this material type. Press it again to go back to the normal view.', [], $dtr),
            $k('Stamp Reviewed is greyed out', 'stamp reviewed greyed, cannot stamp reviewed, reviewed button disabled', 'Stamp Reviewed needs a saved report and the right role. Save the report first; if it stays disabled, ask your supervisor or an administrator.', [], $dtr),
            $k('The overall stamp does not show', 'overall stamp missing, no stamp, result stamp missing, pass stamp not shown', 'The stamp is set when the Status is Complete and at least one test has a rating. Set the Status, press Run Smart Standards & Lookup and save.', [], $dtr),
            $k('A rating shows FAIL but I think it passes', 'rating wrong fail, thinks pass but fail, wrong rating, rating mismatch', 'Check the Material Type, thickness and the readings (decimal point, units), then press Run Smart Standards & Lookup. If the standard used looks wrong, tell an administrator the material type and test.', [], $dtr),
            $k('The thickness-based standard did not change', 'thickness standard not changed, standard by thickness, thickness band, tave standard', 'The thickness average (TAve) picks the standard band. Enter all thickness readings, then press Run Smart Standards & Lookup so the band is chosen again.', [], $dtr),
            $k('Weight Calc and SG Calc buttons on the form', 'weight calc button, sg calc button form, calc buttons material form, calculator buttons form', 'They open the calculators with this report, and Apply to Material Form copies the result back into the form. Save the report afterwards.', [], $dtr),
            $k('How do I use the Shrinkage calculator?', 'shrinkage calc, shrinkage calculator, how to calculate shrinkage, before after length', 'Open Calculators (or Shrinkage Calc on the form), enter the length before and after for each direction, and the shrinkage % is calculated. Apply to Material Form copies it into the report.', [], $dtr + $goCa),
            $k('The form shows numbers with too many decimals', 'too many decimals, long decimals, rounding display, decimals shown', 'Averages are calculated and may show more decimals on screen; the printed sheet rounds them. Type readings with the decimals your test method uses.', [], $dtr),
            $k('I saved a report under the wrong form', 'saved wrong form, wrong report type, fabric saved as leather, wrong form type', 'Reports cannot be moved between forms. Create the report again in the right form with the same Lab Ref No. and ask an administrator to remove the wrong one.', [], $dtr),
            $k('The Lab Ref No. box does not accept my number', 'lab ref box not accept, labref format, invalid lab ref, lab ref rejected', 'Use the lab format: DTP + date (YYYYMMDD) + the form letters and number, for example DTP20261009FBU-1; bonding refs end in -L or -R.', [], $dtr),
            $k('Load Machine Results overwrote my typed values', 'machine overwrote values, load replaced my values, overwrite readings, load machine overwrite', 'Loading fills the readings from the machine file and replaces the same boxes. Retype your manual values after loading, or do not load again. Save when the values are right.', [], $dtr),
            $k('Where is the Material Code box?', 'material code box, where material code, enter material code, material code field', 'In section A (Sample Identification) of the material form: type the code and press Tab to auto-fill from the material master.', [], $dtr + $goMt),
            $k('Why is a test section greyed out?', 'test section greyed, section disabled, cannot type section, greyed fields', 'That section is not used for the chosen Material Type. Check the Material Type; if the test is needed anyway, use Show / Hide All Fields or ask an administrator to change the form layout.', [], $dtr),

            // =========================================================== bonding troubleshooting (20)
            $k('+ New Bonding Report does nothing', 'new bonding report nothing, cannot create bonding, new bonding button not working', 'Refresh the Shoe Bonding page (Ctrl + F5) and press + New Bonding Report again. Then type the Lab Ref No. (ending -L or -R) and the style.', [], $dtr + $goBd),
            $k('Load U60 Machine File finds nothing', 'load u60 nothing, u60 file not found, bonding machine file not found, u60 load fails', 'The U60 machine file is matched by the Lab Ref No. Check the number and that the test is finished and saved on the machine PC. Ask me "check machine file for <Lab Ref No.>" to see whether the file is found.', [], $dtr + ['diagnose' => 'machine_share']),
            $k('The bonding diagram shows the wrong shoe side', 'diagram wrong side, left shows right, wrong shoe sketch side, side mirror', 'The diagram follows the Shoe Side field (Left / Right) and the -L / -R ending. Set the right side, save and open the preview again.', [], $dtr),
            $k('The bonding diagram shows the wrong number of spots', 'diagram wrong spots, sketch wrong points count, 26 points 34 points, wrong sketch points', 'The sketch is chosen from Max Points (the number of spots). Check Max Points matches the shoe; correct it, recalculate and save.', [], $dtr),
            $k('What are the blue leader lines on the bonding diagram?', 'blue leader lines, lines on diagram, leader lines shoe, outside values lines', 'They link each outside value (UTF spot) to its spot on the shoe outline, as on the official VF sketch. Inside values (FTO) sit next to the inner ticks.', [], $dtr),
            $k('Recalculate the bonding result after a correction', 'recalculate bonding after correction, refresh bonding result, update bonding rating, bonding recompute', 'After changing a spot value press the recalculate button on the bonding form, check Min / Max and the ratings, then Save. The preview shows the new values.', [], $dtr + $goBd),
            $k('The bonding Min or Max looks wrong', 'bonding min max wrong, minimum wrong bonding, max value wrong, bonding stats wrong', 'Min and Max are taken from the spot values of each part. A typed value with a wrong decimal point or an empty spot shown as 0 changes them. Fix the spot values and recalculate.', [], $dtr),
            $k('How is TOLERABLE decided for bonding?', 'bonding tolerable rule, bonding tolerance, tolerable bonding how, bonding grey zone', 'Each shoe part is compared with its bonding standard from the standards table: at or above the standard is PASS, inside the tolerance band below it is TOLERABLE, below that is FAIL. The values depend on the age category and part, so check them in the standards list rather than memorising numbers.', [], $dtr + $goCa),
            $k('What standard applies to kids, toddler and adult shoes?', 'kids standard bonding, toddler standard, adult bonding standard, children bonding std, age category standard', 'The bonding standard depends on the Age Category (Adult, Children, Kids, Toddler) and the shoe part. NEXUS-L takes it from the standards table imported from the QC Lab Access database; open Calculators & Standards to see the current values.', [], $dtr + $goCa),
            $k('The bonding report has no Access machine-result page', 'no access page bonding, page 2 missing bonding, machine result page missing, access page missing', 'The official Access page is added only when the Access result for that BondingTestID exists and the Access engine is available on the server. The NEXUS-L sheet itself is complete; tell an administrator if page 2 is required.', [], $pdf),
            $k('The spot values on the diagram are in the wrong place', 'spot values wrong place, values misplaced diagram, numbers not on spot, diagram offset', 'The positions come from the official sketch coordinates for that spot count. Check Max Points and the side first. If they are still off, an administrator can adjust them in the Report Designer > Shoe diagram.', [], $dtr + ['actions' => [$o('Open Report Designer (admin)', 'designer?tab=diagram', true)]]),
            $k('How do I print the bonding report for both shoes together?', 'print both shoes together, left right one print, bonding both sides print, print pair', 'Each side prints from its own record. Open the -L report and print, then the -R report. There is no combined print yet.', [], $dtr + $goBd),
            $k('Find the -R report of my -L bonding report', 'find right report, find -r report, matching side report, other side bonding', 'Search the same Lab Ref with -R instead of -L in the Lab Tracker or Shoe Bonding list, or ask me "open <Lab Ref>-R".', [], $dtr + $goBd),
            $k('The bonding style name did not set the Age Category', 'style name age category, age category not set, bonding category empty, category from style', 'The Age Category is guessed from words in the style name. If it is empty or wrong, choose it by hand; the standard follows the category.', [], $dtr),
            $k('Bonding spot readings are blank after loading', 'bonding readings blank, spots empty after load, u60 values blank, no spot values', 'The U60 file may be for another Lab Ref or still open on the machine PC. Close it there, check the Lab Ref No. and load again.', [], $dtr + ['diagnose' => 'machine_share']),
            $k('What is the FTO line and the UTF line in the bonding table?', 'fto line, utf line, bonding table rows, inside outside spots table', 'UTF are the outside spots around the upper-to-foxing edge and FTO the inside ones; FiTO are the center (filler) values. The table gives Min, Max, the standard and the rating for each.', [], $dtr),
            $k('How do I mark a bonding report as reviewed?', 'bonding reviewed, review bonding report, reviewed by bonding, sign off bonding', 'Fill Reviewed By with the reviewer name and save. The name appears on the printed sheet.', [], $dtr),
            $k('Bonding preview takes long to open', 'bonding preview slow, bonding preview loading, diagram slow, sketch loading slow', 'The preview draws the shoe sketch and places every value, which takes a few seconds. If it never opens, refresh the page (Ctrl + F5) and try again.', [], $dtr),
            $k('Download Official Access PDF button is missing', 'access pdf button missing, no official pdf button, official access pdf hidden', 'The button only shows for bonding reports that have an Access result (BondingTestID). Use Download PDF for the NEXUS-L sheet.', [], $pdf),

            // =========================================================== standards and ratings (15)
            $k('Where do the standards come from?', 'where standards come from, standards source, standards table, access standards, tbl_dtr_standards', 'The standards and tolerances are imported from the QC Lab Access databases into the NEXUS-L standards table. Every rating on the forms is calculated from that table, so a change there changes the ratings after Run Smart Standards & Lookup.', [], $dtr + $goCa),
            $k('What is the pass mark for a test?', 'pass mark, passing value, minimum to pass, threshold pass, pass threshold', 'It depends on the test, the material type and sometimes the thickness, so there is no single number. Open Calculators & Standards and look up the material type: the standard shows the PASS value and the tolerance band.', [], $dtr + $goCa),
            $k('What is the tolerance band?', 'tolerance band, tolerable range, how much below standard, tolerance value', 'The tolerance band is the range just below the standard where a result is TOLERABLE instead of FAIL. Its size is set per test in the standards table; look it up in Calculators & Standards.', [], $dtr + $goCa),
            $k('Why did the ratings change after an update?', 'ratings changed after update, results different now, rating changed old report, standards updated', 'The standards and tolerances were refreshed from the Access databases. Reports are re-rated when you open them and press Run Smart Standards & Lookup. If an old saved result changed, check with your supervisor before printing it again.', [], $dtr),
            $k('How do I see the standard for a material type?', 'see standard material type, lookup standard value, standard for canvas, standard for suede', 'Open Calculators & Standards and search the material type in the Live Master Lookup Explorer, or open the form, choose the Material Type and press Run Smart Standards & Lookup.', [], $dtr + $goCa),
            $k('Is a lower value better or a higher value?', 'lower better higher better, direction of standard, max standard min standard, maximum allowed', 'It depends on the test: strength tests (tensile, tear, bonding) need a value at or above the standard, while tests like abrasion loss or shrinkage need a value at or below it. The form applies the right direction from the standards table.', [], $dtr),
            $k('Who decides the PASS, TOLERABLE or FAIL rules?', 'who decides rules, rating rules owner, pass fail rules who, standards owner', 'The rules come from the VF / lab standards kept in the QC Lab Access databases and imported into NEXUS-L. Changes are made by an administrator with the lab supervisor.', [], $dtr),
            $k('The standard box shows a dash', 'standard dash, standard shows -, no standard value, standard not applicable', 'A dash means there is no standard for this test and material type, so the test is not rated. Tell an administrator if a standard is expected.', [], $dtr),
            $k('Colorfastness grade rules', 'colorfastness grade rules, grey scale grade, staining grade pass, grade 4 3, colour fastness rating', 'Each grade is compared with the minimum grade in the standards table for the material type; any fibre or crocking grade below it rates the test FAIL or TOLERABLE according to the table. Look up the type in Calculators & Standards.', [], $dtr + $goCa),
            $k('Does TOLERABLE count as a pass?', 'tolerable count as pass, is tolerable ok, tolerable accepted, tolerable approve', 'TOLERABLE is between PASS and FAIL: the result is inside the tolerance band. Whether it is accepted depends on the customer and your supervisor; it is shown in amber on the report.', [], $dtr),
            $k('How is the overall result chosen from many tests?', 'overall from many tests, worst result rule, overall result logic, combine ratings', 'The overall result is the worst rating of all rated tests: any FAIL gives FAIL, otherwise any TOLERABLE gives TOLERABLE, otherwise PASS.', [], $dtr),
            $k('The rating is empty even with values', 'rating empty with values, no rating shown, rating blank, not rated', 'The test has no standard for this Material Type, or the standards were not applied. Press Run Smart Standards & Lookup; if it stays empty, there is no standard in the table.', [], $dtr),
            $k('Report a wrong tolerance', 'wrong tolerance, tolerance incorrect, report tolerance error, tolerance value wrong', 'Tell an administrator (Talk to an administrator in this assistant) the material type, test, the tolerance you see and the one in the lab standard. They correct it in the standards table.', [], $dtr),
            $k('Do children and adult shoes have different standards?', 'children adult standards, kids standards different, age based standard, toddler different', 'Yes for bonding and some finished-product tests: the standard depends on the Age Category. The form picks it from the standards table.', [], $dtr),
            $k('Can I override a rating by hand?', 'override rating, manual rating, change rating manually, force pass', 'Ratings are calculated from the values and the standards table. Fix the values or the Material Type instead; a supervisor decision belongs in the remarks.', [], $dtr),

