            $k('The Lab Tracker list is empty', 'tracker empty, lab tracker no rows, list blank tracker, no reports shown', 'Clear the search box and choose All in the category buttons. If it stays empty, the server may be busy: refresh in a minute.', [], $dtr + $goTr),
