            $k('How do I see the files shared in a chat?', 'files shared in chat, media in chat, shared photos, chat attachments list', 'Open the chat details and the Media section to see the files and pictures of that conversation.', [], ['actions' => [$o('Open Inbox', 'inbox')]]),
            $k('A group I created is waiting for approval', 'group waiting approval, group not approved, group pending, approve group', 'Large groups need an administrator approval before they start. Ask an administrator to approve it in the Inbox.', [], ['actions' => [$o('Open Inbox', 'inbox')]]),
