            $k('How do I search inside a chat?', 'search inside chat, find message in chat, chat search, search conversation', 'Open the chat details and use Search in chat to find a word in that conversation.', [], ['actions' => [$o('Open Inbox', 'inbox')]]),
            $k('Can I send a report link in the Inbox?', 'send report link, share lab ref chat, link to report inbox, share report link', 'Yes: copy the address of the open report or the preview link from the assistant and paste it in the chat. The colleague must be signed in to open it.', [], ['actions' => [$o('Open Inbox', 'inbox')]]),

