            $k('How do I add a new answer to the assistant quickly?', 'add answer assistant quickly, teach one answer, new knowledge entry, add bot answer', 'Open the Brain console > Teach / Import, write the question, the answer, keywords and an optional open-page button (for example dtr?tab=bonding), then save.', [], $adm + ['actions' => [$o('Open Brain', 'brain', true)]]),
            $k('How do I reload the built-in answers of the assistant?', 'reload built-in answers, brain seed, php spark brain:seed, refresh knowledge, seed bot', 'Run "php spark brain:seed" in the NEXUS-L folder on the server. It adds new built-in answers and refreshes changed ones; answers taught by administrators are never touched.', [], $adm),
            $k('How do I test the assistant from the command line?', 'test assistant command line, brain ask, php spark brain:ask, bot accuracy test', 'Run "php spark brain:ask your question" to see the best answers and the confidence, or "php spark brain:ask file.tsv" with question<TAB>expected title lines to measure accuracy.', [], $adm),
            $k('The Excel reader reads the wrong cell', 'excel reader wrong cell, reader wrong value, mapping wrong cell, machine map wrong', 'Open Report Designer > Excel readers, pick the reader, use Test with a real Lab Ref to see what each rule reads, correct the cell or row rule and save.', [], $adm + ['actions' => [$o('Open Report Designer', 'designer?tab=excel', true)]]),
            $k('How do I hide a field on the material form?', 'hide field material form, remove field form, form fields designer, hide box', 'Open Report Designer > Form fields, choose the form, untick the field (or rename / reorder it) and save. Users see it after a refresh.', [], $adm + ['actions' => [$o('Open Report Designer', 'designer?tab=form', true)]]),
            $k('Who can open the Report Designer?', 'who can open designer, designer access, designer permission, designer admin only', 'Only administrators. Users who need a layout change ask an administrator.', [], []),
            $k('How do I see unanswered questions to the assistant?', 'unanswered questions, bot did not know, questions without answer, unanswered tab', 'Open the Brain console > Unanswered: every question the assistant could not answer is listed, and you can answer it there so it learns.', [], $adm + ['actions' => [$o('Open Brain', 'brain', true)]]),
            $k('How do I retire an old answer?', 'retire answer, disable knowledge, old answer off, archive answer', 'Open the Brain console > Knowledge, find the answer and change its status to retired. Built-in answers that are out of date are retired by brain:seed.', [], $adm + ['actions' => [$o('Open Brain', 'brain', true)]]),
            $k('How do I rebuild the minified assets?', 'rebuild minified assets, node build, build.js, minify js, public assets min', 'On the server run "cd tools/build" then "node build.js". It regenerates public/assets/min/ after a JavaScript or CSS change.', [], $adm),
            $k('How do I run the database migrations?', 'run migrations, php spark migrate, database update, new tables', 'Run "php spark migrate" in the NEXUS-L folder after an update that adds migrations. Back up dbnexus first.', [], $adm),
            $k('How do I distribute the InterLink Sender to users?', 'distribute sender, give extension to users, sender zip download, share sender', 'The sender zip is offered by NEXUS-L at downloads/nexus-l-interlink-sender.zip when a user presses Send without it. Keep that zip updated when tools/interlink-sender changes.', [], $adm),
            $k('The Brain health shows a folder not writable', 'brain folder not writable, brain health red, backup folder error, c brain d brain', 'The Brain backup folders (D:\\html\\Brain and C:\\Brain by default) must exist and be writable by the web server. Fix the folder permissions or change the locations in the Brain settings.', [], $adm + ['diagnose' => 'brain', 'actions' => [$o('Open Health', 'brain?tab=health', true)]]),

            // =========================================================== Help, assistant and general (15)
            $k('What can I ask the assistant to generate?', 'what can assistant generate, bot create file, generate request, make file bot', 'Ask for a report by its Lab Ref No. with "pdf", "preview" or "print" and I give buttons that open its print preview (Download PDF is there). For InterLink, Generate Report on the Upload Form builds <LabRef>_TestReport.pdf. Bonding reports also have Download Official Access PDF.', [], []),
            $k('The help page says the Sync Center works in the background', 'help page sync center background, help outdated, help says queue selected, help sign in once', 'That part of the Help page describes the old shared InterLink connection. Today every PIC signs in to InterLink with their own account, and reports are sent with 1-Click Send (NEXUS-L InterLink Sender) or the fill bookmark.', [], ['page_match' => 'help', 'actions' => [$o('Open InterLink Sync', 'interlink')]]),
            $k('What changed in NEXUS-L recently?', 'what changed recently, new features, latest changes, whats new', 'Recent changes: Generate Report on the InterLink Upload Form, 1-Click Send with the NEXUS-L InterLink Sender, the official VF shoe sketch on bonding reports, Download Official Access PDF, and standards and tolerances imported from the Access databases.', [], []),
            $k('Is NEXUS-L replacing the Access databases?', 'replace access, access databases, digital test report access, still use access', 'NEXUS-L brings the QC Lab Access forms (Digital Test Report) to the web with the same data, standards and report layouts. Ask your supervisor which one to use for daily work during the change-over.', [], []),
            $k('Where is the old Access data?', 'old access data, access records, accdb data, historic reports access', 'The Access records were migrated into NEXUS-L, so old reports open from the Lab Tracker. The original files stay with the lab administrators.', [], $goTr),
            $k('The assistant opened the wrong report', 'assistant opened wrong report, bot wrong lab ref, wrong record assistant', 'I open the first match of the Lab Ref you typed. Type the full number including the -L / -R ending; I also list other matches as extra buttons.', [], []),
            $k('Can the assistant tell me the standard value?', 'assistant standard value, bot tell standard, ask standard number, what is standard for', 'I do not keep standard numbers in my answers, because they live in the standards table and can change. Open Calculators & Standards and look up the material type, or press Run Smart Standards & Lookup on the form.', [], $goCa),
            $k('What does the confidence of the assistant mean?', 'assistant confidence, bot confidence percent, how sure assistant, confidence score', 'It shows how well the answer matches your question. When it is low I offer related answers or the button to talk to an administrator.', [], []),
            $k('How do I ask the assistant about a machine file?', 'ask machine file assistant, check machine file bot, machine file for lab ref, readings file check', 'Type "check machine file for <Lab Ref No.>". I tell you whether the file is found and how many readings it has, and give a button to open the report.', [], []),
            $k('What should I do when a page shows an error toast?', 'error toast, red toast, error message bottom, notification error', 'Read the message: it usually says what to fix (a missing Lab Ref, no PDF, a sign-in). Ask me with the same words to get the steps, or talk to an administrator if it repeats.', [], []),
            $k('How do I go to QC Lab Reports?', 'go to qc lab reports, open dtr page, lab reports page, qc lab menu', 'Use QC Lab Reports in the sidebar; it opens the Lab Tracker with tabs for Material Tests, Shoe Bonding and Calculators.', [], $goTr),
            $k('How do I go to InterLink Sync?', 'go to interlink sync, interlink menu, open interlink page, sync page', 'Use InterLink Sync in the sidebar. It has the InterLink search grid, the Upload Form and the Send a report to InterLink panel.', [], $goIl),
            $k('Why does NEXUS-L need Chrome or Edge on the server?', 'why chrome on server, edge on server, headless browser server, pdf needs chrome', 'Download PDF and Generate Report render the report with headless Chrome / Edge on the server so the PDF looks exactly like the screen sheet. Without it, use Print Report / Save as PDF in your browser.', [], $pdf),
            $k('Which page should I use to send a bonding report?', 'send bonding report page, bonding to interlink, shb send interlink, whole shoe bonding interlink', 'The same InterLink Sync page: pick the Application No. and the bonding Lab Reference (-L or -R), then Generate Report and send with 1 click. The PDF includes the shoe diagram.', [], $il + $goIl),
